   1: //! Job logs — one participant's forensic record of one run (JOB_LOGS jl-1a).
   2: //!
   3: //! `docs/plan/JOB_LOGS.md` ("Log keys and event schema"; "Crash safety,
   4: //! pruning and backpressure") is the contract this module implements:
   5: //!
   6: //! - **Schema.** One JSON [`Event`] per line, each with a wall-clock
   7: //!   timestamp, a sequence number and a `kind`. The first event is
   8: //!   `run-start`, carrying [`FORMAT`] and [`VERSION`]. Readers skip fields
   9: //!   they do not know and read a kind they do not know as
  10: //!   [`EventBody::Unknown`], so adding a field or a kind is not a break; a
  11: //!   change an older reader would misread bumps [`VERSION`].
  12: //! - **Key.** A log is keyed by run ID + participant + role + attempt
  13: //!   ([`LogKey`]), so one daemon that plays two roles in one run writes two
  14: //!   logs, never one interleaved file.
  15: //! - **Writing.** [`LogWriter::start`] appends whole lines to
  16: //!   `<key>.partial.jsonl` from a thread of its own, fed through a bounded
  17: //!   queue: when the thread falls behind, the producer waits rather than
  18: //!   drop an event, because a log with holes misleads. The partial is synced
  19: //!   at every phase change and every few seconds. [`LogWriter::finish`]
  20: //!   writes `run-end`, compresses the partial to `<key>.jsonl.gz` through a
  21: //!   temp file and one rename, removes the partial, then prunes the folder.
  22: //! - **Ownership.** A writer holds an exclusive lock on a sidecar
  23: //!   `<key>.lock` for its whole life. The lock is on a separate file because
  24: //!   a Windows lock on the partial itself would stop a reader from serving
  25: //!   the active log.
  26: //! - **Crash.** [`recover`] (run at startup) finishes every partial whose
  27: //!   lock it can take — its writer is gone — with a `run-end` marked
  28: //!   interrupted. [`open_log`] tolerates the torn last line a crash leaves.
  29: //! - **Retention.** [`prune`] keeps the newest `keep` finished logs, under a
  30: //!   folder lock; it never touches a partial or any file that is not a log.
  31: //! - **Logging never fails a transfer** (R17). Nothing here returns an error
  32: //!   to the transfer: if the log cannot be written, logging stops, a
  33: //!   `log-incomplete` event is attempted, later events are dropped (so a
  34: //!   producer never waits on a dead log), and the [`LogReport`] says the log
  35: //!   is incomplete and why.
  36: 
  37: use flate2::{bufread::MultiGzDecoder, write::GzEncoder, Compression};
  38: use serde::{Deserialize, Serialize};
  39: use std::fs::{self, File, OpenOptions, TryLockError};
  40: use std::io::{self, BufRead, BufReader, BufWriter, Read, Seek, SeekFrom, Write};
  41: use std::path::{Path, PathBuf};
  42: use std::thread::JoinHandle;
  43: use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};
  44: 
  45: /// The `format` every log's `run-start` event carries.
  46: pub const FORMAT: &str = "blit-job-log";
  47: /// The schema version this build writes.
  48: pub const VERSION: u32 = 1;
  49: /// How many finished logs a machine keeps when its settings do not say (R7).
  50: pub const DEFAULT_KEEP: usize = 50;
  51: 
  52: const PARTIAL_SUFFIX: &str = ".partial.jsonl";
  53: const FINISHED_SUFFIX: &str = ".jsonl.gz";
  54: const TEMP_SUFFIX: &str = ".jsonl.gz.tmp";
  55: const LOCK_SUFFIX: &str = ".lock";
  56: /// The folder-wide lock [`prune`] holds. Not a log name: a key has four parts.
  57: const PRUNE_LOCK: &str = "prune.lock";
  58: 
  59: /// How many events may wait for the writer before a producer waits too.
  60: const QUEUE_DEPTH: usize = 4096;
  61: /// The longest a written event stays unsynced.
  62: const SYNC_INTERVAL: Duration = Duration::from_secs(2);
  63: /// How long the writer sleeps when nothing is waiting to be synced.
  64: const IDLE_WAIT: Duration = Duration::from_secs(3600);
  65: const LONGEST_ID: usize = 64;
  66: 
  67: /// `run-end`'s detail when every handle to a log went away without `finish`.
  68: const UNCLOSED_NOTE: &str = "the run ended without closing its log";
  69: /// `run-end`'s detail when [`recover`] finishes a log its process left behind.
  70: const RECOVERED_NOTE: &str =
  71:     "the process ended before the log was finished; recovered at the next start";
  72: 
  73: /// The part a participant played in a run.
  74: #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
  75: #[serde(rename_all = "kebab-case")]
  76: pub enum Role {
  77:     /// The machine where the command was typed.
  78:     Initiator,
  79:     /// A daemon serving the files being sent.
  80:     Source,
  81:     /// A daemon receiving them.
  82:     Destination,
  83: }
  84: 
  85: impl Role {
  86:     pub fn as_str(self) -> &'static str {
  87:         match self {
  88:             Role::Initiator => "initiator",
  89:             Role::Source => "source",
  90:             Role::Destination => "destination",
  91:         }
  92:     }
  93: 
  94:     fn parse(text: &str) -> Option<Self> {
  95:         [Role::Initiator, Role::Source, Role::Destination]
  96:             .into_iter()
  97:             .find(|role| role.as_str() == text)
  98:     }
  99: }
 100: 
 101: /// Which log: run ID + participant + role + attempt.
 102: ///
 103: /// The parts become the log's file name, so the two IDs are limited to 1–64
 104: /// lowercase ASCII letters, digits, `-` and `_` — nothing that could leave
 105: /// the log folder, and no two keys a case-insensitive file system would take
 106: /// for one.
 107: #[derive(Clone, Debug, PartialEq, Eq, Hash)]
 108: pub struct LogKey {
 109:     run_id: String,
 110:     participant: String,
 111:     role: Role,
 112:     attempt: u32,
 113: }
 114: 
 115: impl LogKey {
 116:     pub fn new(
 117:         run_id: impl Into<String>,
 118:         participant: impl Into<String>,
 119:         role: Role,
 120:         attempt: u32,
 121:     ) -> eyre::Result<Self> {
 122:         let run_id = run_id.into();
 123:         let participant = participant.into();
 124:         check_id("run ID", &run_id)?;
 125:         check_id("participant ID", &participant)?;
 126:         Ok(Self {
 127:             run_id,
 128:             participant,
 129:             role,
 130:             attempt,
 131:         })
 132:     }
 133: 
 134:     pub fn run_id(&self) -> &str {
 135:         &self.run_id
 136:     }
 137: 
 138:     pub fn participant(&self) -> &str {
 139:         &self.participant
 140:     }
 141: 
 142:     pub fn role(&self) -> Role {
 143:         self.role
 144:     }
 145: 
 146:     pub fn attempt(&self) -> u32 {
 147:         self.attempt
 148:     }
 149: 
 150:     /// The name every file of this log starts with:
 151:     /// `<run>.<participant>.<role>.<attempt>`.
 152:     pub fn file_stem(&self) -> String {
 153:         format!(
 154:             "{}.{}.{}.{}",
 155:             self.run_id,
 156:             self.participant,
 157:             self.role.as_str(),
 158:             self.attempt
 159:         )
 160:     }
 161: 
 162:     /// The key a [`file_stem`](Self::file_stem) was made from; `None` for
 163:     /// any other name.
 164:     pub fn from_file_stem(stem: &str) -> Option<Self> {
 165:         let mut parts = stem.split('.');
 166:         let (run_id, participant, role, attempt) =
 167:             (parts.next()?, parts.next()?, parts.next()?, parts.next()?);
 168:         if parts.next().is_some() {
 169:             return None;
 170:         }
 171:         let number: u32 = attempt.parse().ok()?;
 172:         // `parse` also takes "+1" and "01", which `file_stem` never writes.
 173:         if number.to_string() != attempt {
 174:             return None;
 175:         }
 176:         Self::new(run_id, participant, Role::parse(role)?, number).ok()
 177:     }
 178: }
 179: 
 180: fn check_id(what: &str, id: &str) -> eyre::Result<()> {
 181:     let allowed = |byte: u8| {
 182:         byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'-' || byte == b'_'
 183:     };
 184:     if id.is_empty() || id.len() > LONGEST_ID || !id.bytes().all(allowed) {
 185:         eyre::bail!(
 186:             "a job log's {what} must be 1–{LONGEST_ID} lowercase letters, digits, '-' or '_' (got {id:?})"
 187:         );
 188:     }
 189:     Ok(())
 190: }
