 192: /// One line of a log.
 193: #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
 194: pub struct Event {
 195:     /// When the event was recorded, in milliseconds since the Unix epoch.
 196:     pub ts_ms: u64,
 197:     /// The event's place in its log, from 0; a complete log has no gaps.
 198:     pub seq: u64,
 199:     #[serde(flatten)]
 200:     pub body: EventBody,
 201: }
 202: 
 203: /// What an event says; `kind` on the wire.
 204: #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
 205: #[serde(tag = "kind", rename_all = "kebab-case")]
 206: pub enum EventBody {
 207:     /// Always the first event: the log's format, version and identity, and
 208:     /// the run it records. The writer records it.
 209:     RunStart(Box<RunStart>),
 210:     /// A phase (`scan`, `transfer`, `delete`, …) starting or ending. The
 211:     /// log is synced at each one.
 212:     Phase { name: String, state: PhaseState },
 213:     /// A file that landed, and its size.
 214:     FileCopied { path: String, bytes: u64 },
 215:     /// A file removed — from the destination by a mirror, from the source by
 216:     /// a move.
 217:     FileDeleted { path: String },
 218:     /// A file that did not land, and why.
 219:     FileFailed { path: String, reason: String },
 220:     /// Work outstanding but nothing moving for `idle_ms`.
 221:     Stall { idle_ms: u64, detail: String },
 222:     /// A line of what `-v` shows — scan time, rate, workers, the plan, how
 223:     /// files were batched — recorded whether or not `-v` was given.
 224:     Diagnostic { message: String },
 225:     /// The run's closing counts.
 226:     Summary(Summary),
 227:     /// The last event of a log that was closed: how the run ended. The
 228:     /// writer records it.
 229:     RunEnd {
 230:         outcome: Outcome,
 231:         #[serde(default, skip_serializing_if = "Option::is_none")]
 232:         detail: Option<String>,
 233:     },
 234:     /// Logging stopped here, for `reason`; nothing after it was kept.
 235:     LogIncomplete { reason: String },
 236:     /// A kind this build does not know, from a newer writer.
 237:     #[serde(other)]
 238:     Unknown,
 239: }
