 241: /// `run-start`'s fields.
 242: #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
 243: pub struct RunStart {
 244:     pub format: String,
 245:     pub version: u32,
 246:     pub run_id: String,
 247:     pub participant: String,
 248:     pub role: Role,
 249:     pub attempt: u32,
 250:     /// The machine's host name at the time — for people; the participant
 251:     /// ID is the identity (hostnames change).
 252:     #[serde(default)]
 253:     pub host: String,
 254:     /// The blit build that wrote the log.
 255:     #[serde(default)]
 256:     pub build: String,
 257:     pub run: RunInfo,
 258: }
