 358: /// One log being written (see the module docs). Dropping it without
 359: /// [`finish`](Self::finish) closes the log as interrupted once every
 360: /// [`LogSender`] is gone too.
 361: pub struct LogWriter {
 362:     sender: LogSender,
 363:     thread: Option<JoinHandle<LogReport>>,
 364:     /// Why the writer thread could not be started.
 365:     spawn_error: Option<String>,
 366: }
 367: 
 368: impl LogWriter {
 369:     /// Start the log `key` in `dir`, recording `run-start` with `run`.
 370:     /// Finishing it later prunes `dir` to the newest `keep` finished logs.
 371:     ///
 372:     /// Returns at once: the folder and files are made on the writer's
 373:     /// thread, and a failure there leaves an incomplete log, never an error.
 374:     pub fn start(dir: &Path, key: LogKey, run: RunInfo, keep: usize) -> Self {
 375:         Self::start_tuned(dir, key, run, Tuning::new(keep))
 376:     }
 377: 
 378:     fn start_tuned(dir: &Path, key: LogKey, run: RunInfo, tuning: Tuning) -> Self {
 379:         let (tx, rx) = flume::bounded(tuning.queue_depth);
 380:         let started_ms = now_ms();
 381:         let dir = dir.to_path_buf();
 382:         let spawned = std::thread::Builder::new()
 383:             .name("blit-job-log".into())
 384:             .spawn(move || write_log(dir, key, run, started_ms, rx, tuning));
 385:         let (thread, spawn_error) = match spawned {
 386:             Ok(thread) => (Some(thread), None),
 387:             Err(error) => (
 388:                 None,
 389:                 Some(format!("could not start the log writer: {error}")),
 390:             ),
 391:         };
 392:         Self {
 393:             sender: LogSender { tx },
 394:             thread,
 395:             spawn_error,
 396:         }
 397:     }
 398: 
 399:     pub fn sender(&self) -> LogSender {
 400:         self.sender.clone()
 401:     }
 402: 
 403:     pub fn record(&self, body: EventBody) {
 404:         self.sender.record(body);
 405:     }
 406: 
 407:     pub async fn record_async(&self, body: EventBody) {
 408:         self.sender.record_async(body).await;
 409:     }
 410: 
 411:     /// Close the log: record `run-end`, compress the log into place and
 412:     /// prune the folder. Blocks until done — compressing a large log takes
 413:     /// a moment — so async code calls it through `spawn_blocking`.
 414:     pub fn finish(mut self, outcome: Outcome, detail: Option<String>) -> LogReport {
 415:         let Some(thread) = self.thread.take() else {
 416:             return LogReport {
 417:                 path: None,
 418:                 complete: false,
 419:                 problem: self.spawn_error.take(),
 420:             };
 421:         };
 422:         let _ = self.sender.tx.send(Msg::Finish { outcome, detail });
 423:         thread.join().unwrap_or_else(|_| LogReport {
 424:             path: None,
 425:             complete: false,
 426:             problem: Some("the log writer stopped unexpectedly".into()),
 427:         })
 428:     }
 429: }
