 431: struct Tuning {
 432:     keep: usize,
 433:     queue_depth: usize,
 434:     sync_interval: Duration,
 435:     /// The append that would write this `seq` fails once.
 436:     #[cfg(test)]
 437:     fail_at_seq: Option<u64>,
 438:     /// The writer waits for this before it starts.
 439:     #[cfg(test)]
 440:     start_gate: Option<flume::Receiver<()>>,
 441: }
 442: 
 443: impl Tuning {
 444:     fn new(keep: usize) -> Self {
 445:         Self {
 446:             keep,
 447:             queue_depth: QUEUE_DEPTH,
 448:             sync_interval: SYNC_INTERVAL,
 449:             #[cfg(test)]
 450:             fail_at_seq: None,
