 457: /// The writer thread.
 458: fn write_log(
 459:     dir: PathBuf,
 460:     key: LogKey,
 461:     run: RunInfo,
 462:     started_ms: u64,
 463:     rx: flume::Receiver<Msg>,
 464:     tuning: Tuning,
 465: ) -> LogReport {
 466:     #[cfg(test)]
 467:     if let Some(gate) = &tuning.start_gate {
 468:         let _ = gate.recv();
 469:     }
 470:     let mut writer = Writer::open(dir, key.file_stem(), &tuning);
 471:     writer.append(
 472:         started_ms,
 473:         EventBody::RunStart(Box::new(RunStart {
 474:             format: FORMAT.into(),
 475:             version: VERSION,
 476:             run_id: key.run_id,
 477:             participant: key.participant,
 478:             role: key.role,
 479:             attempt: key.attempt,
 480:             host: hostname::get()
 481:                 .map(|name| name.to_string_lossy().into_owned())
 482:                 .unwrap_or_default(),
 483:             build: crate::transfer_session::session_build_id().into(),
 484:             run,
 485:         })),
 486:     );
 487:     let (outcome, detail) = loop {
 488:         match rx.recv_timeout(writer.until_sync(tuning.sync_interval)) {
 489:             Ok(Msg::Event { ts_ms, body }) => {
 490:                 let phase = matches!(body, EventBody::Phase { .. });
 491:                 writer.append(ts_ms, body);
 492:                 if phase || writer.until_sync(tuning.sync_interval).is_zero() {
 493:                     writer.sync();
 494:                 }
 495:             }
 496:             Ok(Msg::Finish { outcome, detail }) => break (outcome, detail),
 497:             Err(flume::RecvTimeoutError::Timeout) => writer.sync(),
 498:             Err(flume::RecvTimeoutError::Disconnected) => {
 499:                 break (Outcome::Interrupted, Some(UNCLOSED_NOTE.into()))
 500:             }
 501:         }
 502:     };
 503:     // A handle still recording now fails at once instead of waiting on a
 504:     // queue no one drains.
 505:     drop(rx);
 506:     writer.append(now_ms(), EventBody::RunEnd { outcome, detail });
 507:     writer.sync();
 508:     writer.finish(tuning.keep)
 509: }
 510: 
 511: /// The writer thread's state for one log.
 512: struct Writer {
 513:     dir: PathBuf,
 514:     stem: String,
 515:     /// The sidecar lock, held from opening the log until it is finished.
 516:     lock: Option<File>,
 517:     /// The partial being appended to; `None` once logging has stopped.
 518:     file: Option<PartialFile>,
 519:     report: LogReport,
 520: }
 521: 
 522: impl Writer {
 523:     fn open(dir: PathBuf, stem: String, tuning: &Tuning) -> Self {
 524:         let mut writer = Writer {
 525:             dir,
 526:             stem,
 527:             lock: None,
 528:             file: None,
 529:             report: LogReport::default(),
 530:         };
 531:         match open_partial(&writer.dir, &writer.stem) {
 532:             Ok((lock, file)) => {
 533:                 writer.report.path = Some(path_of(&writer.dir, &writer.stem, PARTIAL_SUFFIX));
 534:                 writer.lock = Some(lock);
 535:                 writer.file = Some(PartialFile {
 536:                     out: BufWriter::with_capacity(64 * 1024, file),
 537:                     line: Vec::new(),
 538:                     next_seq: 0,
 539:                     unsynced: false,
 540:                     last_sync: Instant::now(),
 541:                     #[cfg(test)]
 542:                     fail_at_seq: tuning.fail_at_seq,
 543:                 });
 544:             }
 545:             Err(error) => {
 546:                 writer.report.problem = Some(format!(
 547:                     "could not start the log in {}: {error}",
 548:                     writer.dir.display()
 549:                 ))
 550:             }
 551:         }
 552:         #[cfg(not(test))]
 553:         let _ = tuning;
 554:         writer
 555:     }
 556: 
 557:     fn append(&mut self, ts_ms: u64, body: EventBody) {
 558:         let Some(file) = self.file.as_mut() else {
 559:             return;
 560:         };
 561:         if let Err(error) = file.append(ts_ms, body) {
 562:             self.stop(error);
 563:         }
 564:     }
 565: 
 566:     fn sync(&mut self) {
 567:         let Some(file) = self.file.as_mut() else {
 568:             return;
 569:         };
 570:         if !file.unsynced {
 571:             return;
 572:         }
 573:         if let Err(error) = file.sync() {
 574:             self.stop(error);
 575:         }
 576:     }
 577: 
 578:     /// How long until what was written is due to be synced.
 579:     fn until_sync(&self, interval: Duration) -> Duration {
 580:         match &self.file {
 581:             Some(file) if file.unsynced => interval.saturating_sub(file.last_sync.elapsed()),
 582:             _ => IDLE_WAIT,
 583:         }
 584:     }
 585: 
 586:     /// Logging stops at the first write that fails; the transfer goes on.
 587:     fn stop(&mut self, error: io::Error) {
 588:         let reason = format!("could not write the log: {error}");
 589:         if let Some(mut file) = self.file.take() {
 590:             // Best effort. The failed write may have left part of a line, so
 591:             // end it first and the marker stands as a line of its own.
 592:             let _ = file.out.write_all(b"\n").and_then(|()| {
 593:                 file.append(
 594:                     now_ms(),
 595:                     EventBody::LogIncomplete {
 596:                         reason: reason.clone(),
 597:                     },
 598:                 )?;
 599:                 file.sync()
 600:             });
 601:         }
 602:         self.report.problem.get_or_insert(reason);
 603:     }
 604: 
 605:     fn finish(mut self, keep: usize) -> LogReport {
 606:         self.report.complete = self.file.is_some();
 607:         // Close the partial before compressing it; it was synced already.
 608:         drop(self.file.take());
 609:         let Some(lock) = self.lock.take() else {
 610:             return self.report;
 611:         };
 612:         match compress_into_place(&self.dir, &self.stem) {
 613:             Ok(finished) => self.report.path = Some(finished),
 614:             Err(error) => {
 615:                 self.report.problem.get_or_insert_with(|| {
 616:                     format!("could not finish the log (the next start finishes it): {error}")
 617:                 });
 618:                 return self.report;
 619:             }
 620:         }
 621:         drop(lock);
 622:         let _ = fs::remove_file(path_of(&self.dir, &self.stem, LOCK_SUFFIX));
 623:         if let Err(error) = prune(&self.dir, keep) {
 624:             log::warn!("job logs: pruning {} failed: {error}", self.dir.display());
 625:         }
 626:         self.report
 627:     }
 628: }
 629: 
 630: struct PartialFile {
 631:     out: BufWriter<File>,
 632:     /// Each event is serialized here first, so the file only ever receives
 633:     /// whole lines.
 634:     line: Vec<u8>,
 635:     next_seq: u64,
 636:     unsynced: bool,
 637:     last_sync: Instant,
 638:     #[cfg(test)]
 639:     fail_at_seq: Option<u64>,
 640: }
 641: 
 642: impl PartialFile {
 643:     fn append(&mut self, ts_ms: u64, body: EventBody) -> io::Result<()> {
 644:         self.line.clear();
 645:         serde_json::to_writer(
 646:             &mut self.line,
