 926:     let lock = open_lock_file(&dir.join(PRUNE_LOCK))?;
 927:     lock.lock()?;
 928:     let mut finished = Vec::new();
 929:     for entry in fs::read_dir(dir)?.flatten() {
 930:         let name = entry.file_name();
 931:         let Some(stem) = name.to_str().and_then(|n| n.strip_suffix(FINISHED_SUFFIX)) else {
 932:             continue;
 933:         };
