 935:             continue;
 936:         }
 937:         let Ok(meta) = entry.metadata() else { continue };
 938:         let Ok(modified) = meta.modified() else {
 939:             continue;
 940:         };
 941:         if meta.is_file() {
 942:             finished.push((modified, entry.path()));
 943:         }
 944:     }
