 838: fn recover_one(dir: &Path, stem: &str) -> io::Result<Recovered> {
 839:     let lock_path = path_of(dir, stem, LOCK_SUFFIX);
 840:     let lock = open_lock_file(&lock_path)?;
 841:     match lock.try_lock() {
 842:         Ok(()) => {}
 843:         Err(TryLockError::WouldBlock) => return Ok(Recovered::Live),
 844:         Err(TryLockError::Error(error)) => return Err(error),
 845:     }
 846:     let partial = path_of(dir, stem, PARTIAL_SUFFIX);
 847:     let recovered = if !partial.exists() {
 848:         // A temp file whose partial is gone.
 849:         remove_if_present(&path_of(dir, stem, TEMP_SUFFIX))?;
 850:         Recovered::Tidied
 851:     } else if path_of(dir, stem, FINISHED_SUFFIX).exists() {
 852:         // Finished before the crash; only removing the partial was lost.
 853:         fs::remove_file(&partial)?;
 854:         remove_if_present(&path_of(dir, stem, TEMP_SUFFIX))?;
 855:         Recovered::Tidied
 856:     } else {
 857:         close_interrupted(&partial)?;
 858:         Recovered::Finished(compress_into_place(dir, stem)?)
 859:     };
 860:     drop(lock);
 861:     let _ = fs::remove_file(&lock_path);
 862:     Ok(recovered)
 863: }
