  19: use std::ffi::OsStr;
  20: use std::path::{Path, PathBuf};
  21: 
  22: use crate::generated::FileHeader;
  23: 
  24: /// Reason recorded at manifest intake for a name the destination cannot
  25: /// store (A13). Exact wording is pinned.
  26: pub const DESTINATION_CANNOT_STORE_REASON: &str =
  27:     "source: filename is not valid UTF-8; the destination cannot store it (rename it to transfer)";
  28: 
  29: /// Reason recorded for the second of two manifest entries that collapse
  30: /// to the same text path (A13). Exact prefix is pinned; the raw bytes of
  31: /// the rejected entry follow it when known.
  32: pub const DUPLICATE_MANIFEST_PATH_REASON: &str =
  33:     "source: duplicate manifest path (lossy name collision)";
  34: 
  35: /// The exact bytes of `rel` (a relative path from the scan) joined with
  36: /// `/`, iff at least one component is not valid UTF-8. `None` for every
  37: /// representable name, so the common case costs nothing on the wire.
  38: pub fn raw_relative_bytes(rel: &Path) -> Option<Vec<u8>> {
  39:     let mut lossy = false;
  40:     let mut bytes: Vec<u8> = Vec::new();
  41:     for (i, component) in rel.components().enumerate() {
  42:         let part = component.as_os_str();
  43:         if part.to_str().is_none() {
  44:             lossy = true;
  45:         }
  46:         if i > 0 {
  47:             bytes.push(b'/');
  48:         }
  49:         bytes.extend_from_slice(part.as_encoded_bytes());
  50:     }
  51:     lossy.then_some(bytes)
  52: }
  53: 
  54: /// Whether THIS process, as a destination, can create a name from raw
  55: /// bytes: Linux and the BSDs accept any bytes; macOS (APFS/HFS+) rejects
  56: /// invalid UTF-8 with `EILSEQ`; Windows names are UTF-16 and cannot hold
  57: /// arbitrary bytes at all. The create-time errno remains the per-file
  58: /// backstop ([`is_unrepresentable_name_error`]).
  59: pub const fn destination_can_store_raw_names() -> bool {
  60:     cfg!(all(unix, not(target_os = "macos")))
  61: }
  62: 
  63: /// Whether `error` from a create/open is the filesystem refusing the
  64: /// bytes of the name itself (`EILSEQ`, or `EINVAL` from a filesystem that
  65: /// validates names) rather than an ordinary I/O failure.
  66: pub fn is_unrepresentable_name_error(error: &std::io::Error) -> bool {
  67:     #[cfg(unix)]
  68:     {
  69:         matches!(
  70:             error.raw_os_error(),
  71:             Some(code) if code == libc::EILSEQ || code == libc::EINVAL
  72:         )
  73:     }
  74:     #[cfg(not(unix))]
  75:     {
  76:         let _ = error;
  77:         false
  78:     }
  79: }
