  81: /// Rebuild the path a raw-name header names on THIS host's filesystem,
  82: /// for bytes THIS PROCESS produced (its own scan's `raw_relative_bytes`)
  83: /// or bytes a capable Unix destination is about to create. Unix: the
  84: /// bytes verbatim. Windows: the bytes are the WTF-8 this same process's
  85: /// scan produced, so they round-trip exactly — never call this with
  86: /// bytes received from a peer on a host that cannot store raw names;
  87: /// use [`path_from_received_raw`] for those (cr-ssc5-3).
  88: pub fn path_from_raw(raw: &[u8]) -> PathBuf {
  89:     #[cfg(unix)]
  90:     {
  91:         use std::os::unix::ffi::OsStrExt as _;
  92:         PathBuf::from(OsStr::from_bytes(raw))
  93:     }
  94:     #[cfg(windows)]
  95:     {
  96:         // SAFETY: the only producer of `raw_relative_path` on a Windows
  97:         // source is `raw_relative_bytes` in this same process, which
  98:         // took the bytes from `OsStr::as_encoded_bytes`; the Windows
  99:         // destination never creates from raw bytes
 100:         // (`destination_can_store_raw_names` is false), so every byte
 101:         // string that reaches here is this host's own WTF-8 encoding.
 102:         // Split on the wire separator and rebuild with the native one.
 103:         let mut out = PathBuf::new();
 104:         for piece in raw.split(|b| *b == b'/') {
 105:             let os_piece: &OsStr = unsafe { OsStr::from_encoded_bytes_unchecked(piece) };
 106:             out.push(os_piece);
 107:         }
 108:         out
 109:     }
 110:     #[cfg(not(any(unix, windows)))]
 111:     {
 112:         PathBuf::from(String::from_utf8_lossy(raw).into_owned())
 113:     }
 114: }
