 126: /// The on-disk path of `header` under `root`: by raw bytes when the name
 127: /// is not representable as text, by the text otherwise. An empty
 128: /// relative path means "`root` is itself the file".
 129: pub fn source_path(root: &Path, header: &FileHeader) -> PathBuf {
 130:     if let Some(raw) = header.raw_relative_path.as_deref() {
 131:         return root.join(path_from_raw(raw));
 132:     }
 133:     if header.relative_path.is_empty() {
 134:         root.to_path_buf()
 135:     } else {
 136:         root.join(&header.relative_path)
 137:     }
 138: }
