 140: /// Render raw name bytes for a report: printable ASCII as-is, every other
 141: /// byte as `\xNN`, so two names that collapse to one lossy text can still
 142: /// be told apart in the failure block.
 143: pub fn escape_raw(raw: &[u8]) -> String {
 144:     let mut out = String::with_capacity(raw.len());
 145:     for &b in raw {
 146:         if (0x20..0x7f).contains(&b) && b != b'\\' {
 147:             out.push(b as char);
 148:         } else {
 149:             out.push_str(&format!("\\x{b:02x}"));
 150:         }
 151:     }
 152:     out
 153: }
